  let ghost: HTMLElement | undefined;
  if (!s.viewOnly && s.draggable.enabled && s.draggable.showGhost) { … }

  return { board, container, wrap: element, ghost, shapes, shapesBelow, custom, customBelow, autoPieces };
}

