22:export function start(s: State, e: cg.MouchEvent): void {
23:  if (!(s.trustAllEvents || e.isTrusted)) return; // only trust when trustAllEvents is enabled
24:  if (e.buttons !== undefined && e.buttons > 1) return; // only touch or left click
25:  if (e.touches && e.touches.length > 1) return; // support one finger touch only
26:  const bounds = s.dom.bounds(),
27:    position = util.eventPosition(e)!,
28:    orig = board.getKeyAtDomPos(position, board.whitePov(s), bounds);
29:  if (!orig) return;
30:  const piece = s.pieces.get(orig);
31:  const previouslySelected = s.selected;
32:  if (
33:    !previouslySelected &&
34:    s.drawable.enabled &&
35:    (s.drawable.eraseOnMovablePieceClick || !piece || piece.color !== s.turnColor)
36:  )
37:    drawClear(s);
38:  // Prevent touch scroll and create no corresponding mouse event, if there
39:  // is an intent to interact with the board.
40:  if (
41:    e.cancelable !== false &&
42:    (!e.touches || s.blockTouchScroll || piece || previouslySelected || pieceCloseTo(s, position))
43:  )
44:    e.preventDefault();
45:  else if (e.touches) return; // Handle only corresponding mouse event https://github.com/lichess-org/chessground/pull/268
46:
47:  const hadPremove = !!s.premovable.current;
48:  const hadPredrop = !!s.predroppable.current;
49:  s.stats.ctrlKey = e.ctrlKey;
50:  if (s.selected && board.canMove(s, s.selected, orig)) {
51:    anim(state => board.selectSquare(state, orig), s);
52:  } else {
53:    board.selectSquare(s, orig);
54:  }
55:  const stillSelected = s.selected === orig;
56:  const element = pieceElementByKey(s, orig);
57:  if (piece && element && stillSelected && board.isDraggable(s, orig)) {
58:    s.draggable.current = {
59:      orig,
60:      piece,
61:      origPos: position,
62:      pos: position,
63:      started: s.draggable.autoDistance && s.stats.dragged,
64:      element,
65:      previouslySelected,
66:      originTarget: e.target,
67:      keyHasChanged: false,
68:    };
69:    element.cgDragging = true;
70:    element.classList.add('dragging');
71:    // place ghost
72:    const ghost = s.dom.elements.ghost;
73:    if (ghost) {
74:      ghost.className = `ghost ${piece.color} ${piece.role}`;
75:      util.translate(ghost, util.posToTranslate(bounds)(util.key2pos(orig), board.whitePov(s)));
76:      util.setVisible(ghost, true);
77:    }
78:    processDrag(s);
79:  } else {
80:    if (hadPremove) board.unsetPremove(s);
81:    if (hadPredrop) board.unsetPredrop(s);
82:  }
83:  s.dom.redraw();
84:}
85:
86:function pieceCloseTo(s: State, pos: cg.NumberPair): boolean {
87:  const asWhite = board.whitePov(s),
88:    bounds = s.dom.bounds(),
89:    radiusSq = Math.pow((s.touchIgnoreRadius * bounds.width) / 16, 2) * 2;
90:  for (const key of s.pieces.keys()) {
91:    const center = util.computeSquareCenter(key, asWhite, bounds);
92:    if (util.distanceSq(center, pos) <= radiusSq) return true;
93:  }
94:  return false;
95:}
96:
97:export function dragNewPiece(s: State, piece: cg.Piece, e: cg.MouchEvent, force?: boolean): void {
98:  const key: cg.Key = 'a0';
99:  s.pieces.set(key, piece);
100:  s.dom.redraw();
101:
102:  const position = util.eventPosition(e)!;
103:
104:  s.draggable.current = {
105:    orig: key,
106:    piece,
107:    origPos: position,
108:    pos: position,
109:    started: true,
110:    element: () => pieceElementByKey(s, key),
111:    originTarget: e.target,
112:    newPiece: true,
113:    force: !!force,
114:    keyHasChanged: false,
115:  };
116:  processDrag(s);
117:}
118:
119:function processDrag(s: State): void {
120:  requestAnimationFrame(() => {
121:    const cur = s.draggable.current;
122:    if (!cur) return;
123:    // cancel animations while dragging
124:    if (s.animation.current?.plan.anims.has(cur.orig)) s.animation.current = undefined;
125:    // if moving piece is gone, cancel
126:    const origPiece = s.pieces.get(cur.orig);
127:    if (!origPiece || !util.samePiece(origPiece, cur.piece)) cancel(s);
128:    else {
129:      if (!cur.started && util.distanceSq(cur.pos, cur.origPos) >= Math.pow(s.draggable.distance, 2))
130:        cur.started = true;
131:      if (cur.started) {
132:        // support lazy elements
133:        if (typeof cur.element === 'function') {
134:          const found = cur.element();
135:          if (!found) return;
136:          found.cgDragging = true;
137:          found.classList.add('dragging');
138:          cur.element = found;
139:        }
140:
141:        const bounds = s.dom.bounds();
142:        util.translate(cur.element, [
143:          cur.pos[0] - bounds.left - bounds.width / 16,
144:          cur.pos[1] - bounds.top - bounds.height / 16,
145:        ]);
146:
147:        if (s.jsHover) handleJsHover(s, cur);
148:        else cur.keyHasChanged ||= cur.orig !== board.getKeyAtDomPos(cur.pos, board.whitePov(s), bounds);
149:      }
150:    }
151:    processDrag(s);
152:  });
153:}
154:
155:function handleJsHover(s: State, cur: DragCurrent): void {
156:  const hoveredKey = board.getKeyAtDomPos(cur.pos, board.whitePov(s), s.dom.bounds());
